/**
 * Resolves pokeemerald constant names (MAP_*, FLAG_*, VAR_*, SPECIES_*,
 * ITEM_*, MOVE_*) to numbers.
 *
 * The hack's headers mix #defines, arithmetic (`FLAG_HIDDEN_ITEMS_START +
 * 0x1C`) and enums (map_groups.h, generated by the build), so instead of
 * reimplementing a C expression evaluator this compiles a tiny program with
 * the host C compiler against the real headers and runs it. The answer is
 * exactly what the game was compiled with.
 */

import { execFileSync } from "node:child_process";
import fs from "node:fs";
import os from "node:os";
import path from "node:path";
import { POKEEMERALD_DIR } from "../utils/paths.js";

/** Headers every lookup includes. map_groups.h and map_event_ids.h only exist after a build. */
const HEADERS = [
  "constants/global.h",
  "constants/flags.h",
  "constants/vars.h",
  "constants/species.h",
  "constants/items.h",
  "constants/moves.h",
  "constants/map_groups.h",
  "constants/map_event_ids.h",
  "constants/opponents.h",
];

const IDENTIFIER = /^[A-Za-z_][A-Za-z0-9_]*$/;

export class UnknownConstantError extends Error {
  constructor(readonly names: string[]) {
    super(`unknown constant${names.length > 1 ? "s" : ""}: ${names.join(", ")}`);
  }
}

export interface ResolveOptions {
  pokeemeraldDir?: string;
  /** Host C compiler. Default: $CC or "gcc". */
  cc?: string;
}

/** Evaluates each name as a C expression against the hack's headers. */
export function resolveConstants(names: Iterable<string>, opts: ResolveOptions = {}): Map<string, number> {
  const unique = [...new Set(names)];
  const result = new Map<string, number>();
  if (unique.length === 0) return result;
  for (const name of unique) {
    if (!IDENTIFIER.test(name)) throw new Error(`not a constant name: ${JSON.stringify(name)}`);
  }

  const dir = opts.pokeemeraldDir ?? POKEEMERALD_DIR;
  const cc = opts.cc ?? process.env.CC ?? "gcc";
  const tmp = fs.mkdtempSync(path.join(os.tmpdir(), "oak-consts-"));
  try {
    const src = path.join(tmp, "consts.c");
    const exe = path.join(tmp, "consts");
    fs.writeFileSync(
      src,
      [
        "#include <stdio.h>",
        ...HEADERS.map((h) => `#include "${h}"`),
        "int main(void) {",
        ...unique.map((n) => `    printf("%s=%ld\\n", "${n}", (long)(${n}));`),
        "    return 0;",
        "}",
        "",
      ].join("\n"),
    );
    try {
      execFileSync(cc, ["-w", "-I", path.join(dir, "include"), "-o", exe, src], {
        env: { ...process.env, LC_ALL: "C" },
        stdio: ["ignore", "ignore", "pipe"],
      });
    } catch (err) {
      const stderr = String((err as { stderr?: Buffer }).stderr ?? "");
      const missing = [...stderr.matchAll(/'([A-Za-z_][A-Za-z0-9_]*)' undeclared/g)].map((m) => m[1]);
      if (missing.length) throw new UnknownConstantError([...new Set(missing)]);
      throw new Error(`could not evaluate constants with ${cc}:\n${stderr.slice(0, 2000)}`);
    }
    const out = execFileSync(exe, { encoding: "utf8" });
    for (const line of out.split("\n")) {
      const eq = line.indexOf("=");
      if (eq > 0) result.set(line.slice(0, eq), Number(line.slice(eq + 1)));
    }
    return result;
  } finally {
    fs.rmSync(tmp, { recursive: true, force: true });
  }
}

/** Every `#define PREFIX...` name in a header, e.g. all SPECIES_* in constants/species.h. */
export function listDefines(headerText: string, prefix: string): string[] {
  const names: string[] = [];
  const re = new RegExp(`^\\s*#define\\s+(${prefix}[A-Za-z0-9_]*)\\s+\\S`, "gm");
  for (const m of headerText.matchAll(re)) names.push(m[1]);
  return names;
}

export interface MapId {
  group: number;
  num: number;
}

/** Parses the build-generated map_groups.h enum: `MAP_ROUTE104 = (19 | (0 << 8)),` */
export function parseMapGroups(text: string): Map<string, MapId> {
  const maps = new Map<string, MapId>();
  for (const m of text.matchAll(/\b(MAP_[A-Z0-9_]+)\s*=\s*\(\s*(\d+)\s*\|\s*\(\s*(\d+)\s*<<\s*8\s*\)\s*\)/g)) {
    maps.set(m[1], { num: Number(m[2]), group: Number(m[3]) });
  }
  return maps;
}

/**
 * Reverse lookups for readState(): map and species constant names by value.
 * Built once per session from the same headers the ROM was compiled with.
 */
export class ConstantNames {
  private constructor(
    private readonly maps: Map<string, string>,
    private readonly species: Map<number, string>,
  ) {}

  static load(opts: ResolveOptions = {}): ConstantNames {
    const dir = opts.pokeemeraldDir ?? POKEEMERALD_DIR;
    const maps = new Map<string, string>();
    for (const [name, id] of parseMapGroups(fs.readFileSync(path.join(dir, "include/constants/map_groups.h"), "utf8"))) {
      maps.set(`${id.group}.${id.num}`, name);
    }
    const speciesNames = listDefines(fs.readFileSync(path.join(dir, "include/constants/species.h"), "utf8"), "SPECIES_");
    const species = new Map<number, string>();
    for (const [name, value] of resolveConstants(speciesNames, opts)) {
      // First name wins, so SPECIES_EGG-style aliases don't shadow real species.
      if (!species.has(value)) species.set(value, name);
    }
    return new ConstantNames(maps, species);
  }

  mapName(group: number, num: number): string {
    return this.maps.get(`${group}.${num}`) ?? `MAP_${group}_${num}`;
  }

  speciesName(id: number): string {
    return this.species.get(id) ?? `SPECIES_${id}`;
  }
}
